sect2.example:
    Extender Exception


<?php
class CustomException extends Exception
{
    // Redefinir el constructor para que el mensaje no sea opcional
    public function __construct($message, $code = 0, ?Throwable $previous = null) {
        // algo de código

        // Asegurarse de que todo se asigna correctamente
        parent::__construct($message, $code, $previous);
    }

    // Representación personalizada del objeto como string
    public function __toString() {
        return __CLASS__ . ": [{$this->code}]: {$this->message}\n";
    }

    public function customFunction() {
        echo "Una función personalizada para este tipo de excepción\n";
    }
}

try {
    throw new CustomException("Algo ha ocurrido", 5);
} catch (CustomException $e) {
    echo "Excepción personalizada capturada\n", $e;
    $e->customFunction();
}


    &example.outputs;


